<?php declare(strict_types=1); require_once __DIR__ . '/auth.php'; $user=require_login(); ?>
<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><meta name="theme-color" content="#073b3a"><title>Chats móviles | Victor</title><style>
:root{font-family:Inter,system-ui,sans-serif;color:#16252b;background:#eef6f2;--green:#0c6b63;--line:#d7e2df}*{box-sizing:border-box}html,body{height:100%;overflow:hidden}body{margin:0}.top{height:74px;background:#073b3a;color:#fff;padding:13px 16px;display:flex;align-items:center;justify-content:space-between}.top h1{margin:2px 0;font-size:1.25rem}.top a{color:#fff;text-decoration:none;font-size:.85rem}.eyebrow{margin:0;color:#8fcfc1;font-size:.62rem;font-weight:800;letter-spacing:.14em}.app{height:calc(100dvh - 74px);background:#f7faf9;position:relative}.inbox,.chat{height:100%;display:flex;flex-direction:column}.chat{position:fixed;top:74px;right:0;bottom:0;left:0;height:auto;background:#f7faf9;z-index:2}.head{padding:16px;border-bottom:1px solid var(--line);display:flex;justify-content:space-between;align-items:center}.head h2,.chathead h2{margin:0;font-size:1.12rem}.head small{color:#71827f;font-size:.72rem}.user{background:#d9f1e7;color:var(--green);border-radius:20px;padding:7px 10px;font-size:.75rem;font-weight:700}.search{padding:12px 14px}.search span{position:absolute;left:-9999px}.search input{width:100%;border:0;background:#eaf2ef;border-radius:12px;padding:13px;font:inherit;outline:2px solid transparent}.search input:focus{outline-color:#91cfc0}.clients{overflow:auto;flex:1}.client{display:flex;align-items:center;gap:11px;width:100%;padding:14px 16px;border:0;border-bottom:1px solid #edf2f0;background:#fff;text-align:left}.avatar{display:grid;place-items:center;flex:0 0 44px;height:44px;border-radius:50%;background:#94c8bc;color:#074d47;font-weight:800}.copy{display:grid;gap:4px;min-width:0;flex:1}.copy b,.copy small{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.copy small{color:#71827f;font-size:.75rem}.chev{font-size:1.6rem;color:#9aada9}.chathead{padding:10px 12px;border-bottom:1px solid var(--line);display:flex;align-items:center;gap:10px;background:#fff}.chathead button{border:0;background:transparent;color:var(--green);font-size:2rem;line-height:1;padding:0 7px}.chathead>div{flex:1;min-width:0}.chathead h2{margin-top:2px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.status{font-size:.72rem;color:#43827a}.status i{display:inline-block;width:7px;height:7px;border-radius:50%;background:#41ad72;margin-right:4px}.notes{margin:10px 12px 0;border:1px solid var(--line);border-radius:10px;padding:10px;resize:none;min-height:42px;max-height:70px;font:inherit}.messages{flex:1;overflow:auto;padding:14px 11px;display:flex;flex-direction:column;gap:9px;background:linear-gradient(#f7faf9,#eef6f2)}.message{max-width:87%;padding:10px 12px;border-radius:13px;box-shadow:0 1px 2px #17484412}.message p{margin:0;white-space:pre-wrap;line-height:1.4;font-size:.94rem}.message time{display:block;margin-top:4px;font-size:.63rem;color:#71827f}.user-msg{align-self:flex-start;background:#fff;border-top-left-radius:3px}.bot-msg{align-self:flex-end;background:#d9f1e7;border-top-right-radius:3px}.composer{display:flex;gap:7px;padding:9px 10px calc(9px + env(safe-area-inset-bottom));background:#fff;border-top:1px solid var(--line)}.composer textarea{flex:1;resize:none;border:1px solid var(--line);border-radius:20px;padding:10px 13px;font:inherit;min-height:42px}.composer button{border:0;border-radius:20px;background:var(--green);color:#fff;padding:0 14px;font-weight:700}.empty{color:#71827f;text-align:center;padding:30px 15px}.hidden{display:none!important}
</style></head><body><header class="top"><div><p class="eyebrow">LIBERATE DE TUS DEUDAS.CL</p><h1>Conversaciones</h1></div><a href="index.php?logout=1">Salir</a></header><main class="app"><section id="inbox" class="inbox"><div class="head"><div><h2>Chats</h2><small id="sync">Sincronizando...</small></div><span class="user"><?=htmlspecialchars($user['username'])?></span></div><label class="search"><span>Buscar</span><input id="search" placeholder="Buscar nombre o teléfono" autocomplete="off"></label><div id="clients" class="clients">Cargando...</div></section><section id="chat" class="chat hidden"><div class="chathead"><button id="back" type="button" aria-label="Volver a chats">‹</button><div><p class="eyebrow">CONVERSACIÓN</p><h2 id="selected">Cliente</h2></div><span class="status"><i></i>Bot</span></div><textarea id="notes" class="notes" placeholder="Notas internas"></textarea><div id="messages" class="messages"><div class="empty">Cargando mensajes...</div></div><?php if(in_array($user['role']??'', ['victor','tester'], true)): ?><form id="reply" class="composer"><textarea required rows="1" placeholder="Escribe una respuesta..."></textarea><button type="submit">Enviar</button></form><?php endif; ?></section></main><script>
const csrf=<?=json_encode(csrf_token())?>;let current=null,currentClient=null;const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,x=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[x]));async function loadClients(){try{const r=await fetch('api/clients.php?q='+encodeURIComponent($('#search').value)),d=await r.json();$('#clients').innerHTML=d.data.map(c=>`<button class="client" data-phone="${esc(c.phone)}"><span class="avatar">${esc((c.name||c.phone).slice(0,1).toUpperCase())}</span><span class="copy"><b>${esc(c.name||'Sin nombre')}</b><small>${esc(c.phone)} · ${esc(c.status||'new')}</small></span><span class="chev">›</span></button>`).join('')||'<p class="empty">Sin clientes todavía.</p>';document.querySelectorAll('.client').forEach(b=>b.onclick=()=>openChat(b.dataset.phone,d.data.find(c=>c.phone===b.dataset.phone)));$('#sync').textContent='Actualizado ahora'}catch(e){$('#sync').textContent='Error de conexión'}}async function openChat(phone,c,fromHistory=false){current=phone;currentClient=c;$('#selected').textContent=c.name||phone;$('#notes').value=c.notes||'';$('#inbox').classList.add('hidden');$('#chat').classList.remove('hidden');if(!fromHistory)history.pushState({chat:phone},'',location.pathname+'?chat='+encodeURIComponent(phone));await loadConversation()}async function loadConversation(){if(!current)return;const r=await fetch('api/conversations.php?phone='+encodeURIComponent(current)),d=await r.json();$('#messages').innerHTML=d.data.map(m=>`<div class="message ${m.role==='assistant'?'bot-msg':'user-msg'}"><p>${esc(m.content)}</p><time>${esc(m.created_at||'')}</time></div>`).join('')||'<div class="empty">Sin mensajes todavía.</div>';$('#messages').scrollTop=$('#messages').scrollHeight}async function post(url,payload){const r=await fetch(url,{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':csrf},body:JSON.stringify(payload)}),d=await r.json();if(!r.ok)throw Error(d.detail?`${d.error}: ${d.detail}`:(d.error||'No se pudo completar'));return d}function closeChat(){current=null;currentClient=null;$('#chat').classList.add('hidden');$('#inbox').classList.remove('hidden');loadClients()}$('#search').oninput=loadClients;$('#back').onclick=()=>{if(location.search)history.back();else closeChat()};addEventListener('popstate',closeChat);let timer;$('#notes').oninput=()=>{clearTimeout(timer);timer=setTimeout(async()=>{if(current&&currentClient)try{await post('api/update-client.php',{phone:current,status:currentClient.status||'new',notes:$('#notes').value});$('#sync').textContent='Notas guardadas'}catch(e){$('#sync').textContent='Error al guardar'}},700)};const form=$('#reply');if(form)form.onsubmit=async e=>{e.preventDefault();const f=form.querySelector('textarea'),b=form.querySelector('button'),content=f.value.trim();if(!current||!content)return;b.disabled=true;try{await post('api/reply.php',{phone:current,content});f.value='';await loadConversation()}catch(e){alert(e.message)}finally{b.disabled=false}};loadClients();setInterval(async()=>{await loadClients();await loadConversation()},5000);
</script></body></html>
